    # Simple deterministic intra-route local improvement: swap first two if beneficial by id order
    id_to_demand = {c['id']: c['demand'] for c in customers}
    for route in routes:
        if len(route) < 2:
            continue
        # Try a single swap of first two if it reduces lexicographic order of ids
        a, b = route[0], route[1]
        if a > b:
            route[0], route[1] = b, a

